    /// <summary>
    /// Returns approximate 1-based position of a message among messages, which can be found by the specified filter in the chat and topic. Cannot be used in secret chats
    /// </summary>
    public Task<TdLib.TdApi.Objects.Count> GetChatMessagePositionAsync(long chatId = default, MessageTopic topicId = default, SearchMessagesFilter filter = default, long messageId = default)
    {

           using var activity =  StartCallActivity("GetChatMessagePositionAsync", typeof(GetChatMessagePosition).FullName ?? "GetChatMessagePositionAsync");

           try
           {
             return client.GetChatMessagePositionAsync(chatId, topicId, filter, messageId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
